package android.view;import java.util.ArrayList;import java.util.List;import dev.mixer.android.OwnerHostProbe;public class ViewTreeObserver {public interface OnWindowFocusChangeListener {void onWindowFocusChanged(boolean focused);}public boolean alive=true;public final List<OnWindowFocusChangeListener> listeners=new ArrayList<>();public int addCalls,removeCalls;public boolean isAlive(){OwnerHostProbe.hit("ViewTreeObserver.isAlive","entry",this);boolean value=alive;OwnerHostProbe.hit("ViewTreeObserver.isAlive","beforeReturn",this);return value;}public void addOnWindowFocusChangeListener(OnWindowFocusChangeListener listener){OwnerHostProbe.hit("ViewTreeObserver.addOnWindowFocusChangeListener","entry",this);addCalls++;listeners.add(listener);OwnerHostProbe.hit("ViewTreeObserver.addOnWindowFocusChangeListener","beforeReturn",this);}public void removeOnWindowFocusChangeListener(OnWindowFocusChangeListener listener){OwnerHostProbe.hit("ViewTreeObserver.removeOnWindowFocusChangeListener","entry",this);removeCalls++;listeners.removeIf(item->item==listener);OwnerHostProbe.hit("ViewTreeObserver.removeOnWindowFocusChangeListener","beforeReturn",this);}public void hostWindowFocus(boolean focused){for(OnWindowFocusChangeListener listener:List.copyOf(listeners))listener.onWindowFocusChanged(focused);}}
